TWComponent.script:
/**----------------------------------------------------NOTES----------------------------------------------------------**/
// TODO : add each split outstanding amnt
// CURRENTLY : we retrieve MultiTenorDates, Parties, Contarct details.
/**--------------------------------------------------------------------------------------------------------------- ---**/

if (tw.local.isSuccessful && tw.local.queryBCContractResults) {

	/**--------------------------------------------------------------------------------------------------------------*/
	tw.local.ContractDetails.ContractCreation.HScode={};
	tw.local.authStatues = tw.local.queryBCContractResults.AUTHSTAT; // A or U
	tw.local.ContractDetails.ContractCreation.productCode.value = tw.local.queryBCContractResults.ProductCode;
	tw.local.ContractDetails.ContractCreation.baseDate = convertToUTCDate(tw.local.queryBCContractResults.BaseDate);
	tw.local.ContractDetails.ContractCreation.maturityDate = convertToUTCDate(tw.local.queryBCContractResults.MaturityDate);
	tw.local.ContractDetails.ContractCreation.sourceReference = tw.local.ContractDetails.ContractCreation.sourceReference || tw.local.queryBCContractResults.SOURCE;
	tw.local.ContractDetails.ContractCreation.userReference = tw.local.queryBCContractResults.UseRefNum;
	tw.local.ContractDetails.ContractCreation.tenorDays = Number(tw.local.queryBCContractResults.TenorDays);
	tw.local.ContractDetails.ContractCreation.transitDays = Number(tw.local.queryBCContractResults.TransitDays);
	tw.local.ContractDetails.ContractCreation.currency = tw.local.queryBCContractResults.Currency;
	tw.local.ContractDetails.ContractCreation.amount = parseFloat(tw.local.queryBCContractResults.Amount);
	tw.local.ContractDetails.FinancialDetailsFO.collectableAmount = parseFloat(tw.local.queryBCContractResults.Amount);
	tw.local.ContractDetails.FinancialDetailsFO.outstandingAmount = parseFloat(tw.local.queryBCContractResults.OutstandingAmount);
	tw.local.ContractDetails.BasicDetails.operationType.value = tw.local.queryBCContractResults.Operation;
	tw.local.ContractDetails.CustomerInfo.cif = tw.local.queryBCContractResults.CustomerId;
	if(!!tw.local.queryBCContractResults.Contract_Goods_Details){
		tw.local.ContractDetails.ContractCreation.HScode.name=tw.local.queryBCContractResults.Contract_Goods_Details[0].GoodsCode;
		tw.local.ContractDetails.ContractCreation.HScode.value=tw.local.queryBCContractResults.Contract_Goods_Details[0].GoodsDescR;
	}
	/**--------------------------------------------------MULTI TENOR-------------------------------------------------*/
	if (!tw.local.ContractDetails.FinancialDetailsFO.multiTenorDates) tw.local.ContractDetails.FinancialDetailsFO.multiTenorDates = new tw.object.listOf.MultiTenorDates();
	if (tw.local.queryBCContractResults.Contract_Multitnr && tw.local.queryBCContractResults.Contract_Multitnr.listLength > 0) {
		for (var i = 0; i < tw.local.queryBCContractResults.Contract_Multitnr.listLength; i++) {
			if (!tw.local.ContractDetails.FinancialDetailsFO.multiTenorDates[i]) tw.local.ContractDetails.FinancialDetailsFO.multiTenorDates[i] = new tw.object.MultiTenorDates();
			tw.local.ContractDetails.FinancialDetailsFO.multiTenorDates[i].amount = parseFloat(tw.local.queryBCContractResults.Contract_Multitnr[i].BillAmount);
			tw.local.ContractDetails.FinancialDetailsFO.multiTenorDates[i].instalmentBaseDate = convertToUTCDate(tw.local.queryBCContractResults.Contract_Multitnr[i].BaseDate);
			tw.local.ContractDetails.FinancialDetailsFO.multiTenorDates[i].instalmentMaturityDate = convertToUTCDate(tw.local.queryBCContractResults.Contract_Multitnr[i].MaturityDate);
			tw.local.ContractDetails.FinancialDetailsFO.multiTenorDates[i].instalmentTenorDays = tw.local.queryBCContractResults.Contract_Multitnr[i].TNOR;
			var splitRebateAmnt = tw.local.ContractDetails.FinancialDetailsFO.multiTenorDates[i].splitRebateAmnt;
			if (tw.local.queryBCContractResults.Contract_Multitnr[i].RebatAmount != null && tw.local.queryBCContractResults.Contract_Multitnr[i].RebatAmount != undefined)
				tw.local.ContractDetails.FinancialDetailsFO.multiTenorDates[i].splitRebateAmnt = parseFloat(tw.local.queryBCContractResults.Contract_Multitnr[i].RebatAmount);
			else
				tw.local.ContractDetails.FinancialDetailsFO.multiTenorDates[i].splitRebateAmnt = splitRebateAmnt || 0;
		}
	}

	/**-----------------------------------------------PARTIES------------------------------------------------------- */
	tw.local.ContractDetails.Parties = new tw.object.odcParties();
	for (var i = 0; i < tw.local.queryBCContractResults.Contract_Parties.listLength; i++) {
		if (tw.local.queryBCContractResults.Contract_Parties[i].PartyType.replace(" ", "").toLowerCase() == "collectingbank") {
			tw.local.ContractDetails.Parties.collectingBank = tw.local.ContractDetails.Parties.collectingBank || new tw.object.CollectingBank();
			tw.local.ContractDetails.Parties.collectingBank.cif = tw.local.queryBCContractResults.Contract_Parties[i].PartyId;
			tw.local.ContractDetails.Parties.collectingBank.country = tw.local.queryBCContractResults.Contract_Parties[i].PartyCountryCode;
			tw.local.ContractDetails.Parties.collectingBank.address1 = tw.local.queryBCContractResults.Contract_Parties[i].PartyAddress1;
			tw.local.ContractDetails.Parties.collectingBank.address2 = tw.local.queryBCContractResults.Contract_Parties[i].PartyAddress2;
			tw.local.ContractDetails.Parties.collectingBank.address3 = tw.local.queryBCContractResults.Contract_Parties[i].PartyAddress3;
			tw.local.ContractDetails.Parties.collectingBank.language = tw.local.queryBCContractResults.Contract_Parties[i].PartyLang;
			tw.local.ContractDetails.Parties.collectingBank.name = tw.local.queryBCContractResults.Contract_Parties[i].PartyName;
			tw.local.ContractDetails.Parties.collectingBank.id = tw.local.queryBCContractResults.Contract_Parties[i].PartyId;
			tw.local.ContractDetails.Parties.collectingBank.reference = tw.local.queryBCContractResults.Contract_Parties[i].PartyRefNum;
			if (tw.local.queryBCContractResults.Contract_Parties[i].Party_Addr && tw.local.queryBCContractResults.Contract_Parties[i].Party_Addr.listLength > 0) {
				tw.local.ContractDetails.Parties.collectingBank.media = tw.local.queryBCContractResults.Contract_Parties[i].Party_Addr[0].MEDIA;
				tw.local.ContractDetails.Parties.collectingBank.address = tw.local.queryBCContractResults.Contract_Parties[i].Party_Addr[0].ADDR;
			}
		} else if (tw.local.queryBCContractResults.Contract_Parties[i].PartyType == "DRAWEE") {
			tw.local.ContractDetails.Parties.Drawee = tw.local.ContractDetails.Parties.Drawee || new tw.object.Drawee();
			tw.local.ContractDetails.Parties.Drawee.country = tw.local.queryBCContractResults.Contract_Parties[i].PartyCountryCode;
			tw.local.ContractDetails.Parties.Drawee.address1 = tw.local.queryBCContractResults.Contract_Parties[i].PartyAddress1;
			tw.local.ContractDetails.Parties.Drawee.address2 = tw.local.queryBCContractResults.Contract_Parties[i].PartyAddress2;
			tw.local.ContractDetails.Parties.Drawee.address3 = tw.local.queryBCContractResults.Contract_Parties[i].PartyAddress3;
			tw.local.ContractDetails.Parties.Drawee.Language = tw.local.queryBCContractResults.Contract_Parties[i].PartyLang;
			tw.local.ContractDetails.Parties.Drawee.partyName = tw.local.queryBCContractResults.Contract_Parties[i].PartyName;
			tw.local.ContractDetails.Parties.Drawee.partyId = tw.local.queryBCContractResults.Contract_Parties[i].PartyId;
			tw.local.ContractDetails.Parties.Drawee.Reference = tw.local.queryBCContractResults.Contract_Parties[i].PartyRefNum;
		} else if (tw.local.queryBCContractResults.Contract_Parties[i].PartyType == "DRAWER") {
			tw.local.ContractDetails.Parties.Drawer = tw.local.ContractDetails.Parties.Drawer || new tw.object.Drawer();
			tw.local.ContractDetails.Parties.Drawer.country = tw.local.queryBCContractResults.Contract_Parties[i].PartyCountryCode;
			tw.local.ContractDetails.Parties.Drawer.address1 = tw.local.queryBCContractResults.Contract_Parties[i].PartyAddress1;
			tw.local.ContractDetails.Parties.Drawer.address2 = tw.local.queryBCContractResults.Contract_Parties[i].PartyAddress2;
			tw.local.ContractDetails.Parties.Drawer.address3 = tw.local.queryBCContractResults.Contract_Parties[i].PartyAddress3;
			tw.local.ContractDetails.Parties.Drawer.Language = tw.local.queryBCContractResults.Contract_Parties[i].PartyLang;
			tw.local.ContractDetails.Parties.Drawer.partyName = tw.local.queryBCContractResults.Contract_Parties[i].PartyName;
			tw.local.ContractDetails.Parties.Drawer.partyId = tw.local.queryBCContractResults.Contract_Parties[i].PartyId;
			tw.local.ContractDetails.Parties.Drawer.Reference = tw.local.queryBCContractResults.Contract_Parties[i].PartyRefNum;
		} else if (tw.local.queryBCContractResults.Contract_Parties[i].PartyType == "CASE IN NEED") {
			tw.local.ContractDetails.Parties.caseInNeed = tw.local.ContractDetails.Parties.caseInNeed || new tw.object.partyTypes();
			tw.local.ContractDetails.Parties.caseInNeed.partyCIF = tw.local.queryBCContractResults.Contract_Parties[i].PartyId;
			tw.local.ContractDetails.Parties.caseInNeed.country = tw.local.queryBCContractResults.Contract_Parties[i].PartyCountryCode;
			tw.local.ContractDetails.Parties.caseInNeed.address1 = tw.local.queryBCContractResults.Contract_Parties[i].PartyAddress1;
			tw.local.ContractDetails.Parties.caseInNeed.address2 = tw.local.queryBCContractResults.Contract_Parties[i].PartyAddress2;
			tw.local.ContractDetails.Parties.caseInNeed.address3 = tw.local.queryBCContractResults.Contract_Parties[i].PartyAddress3;
			tw.local.ContractDetails.Parties.caseInNeed.language = tw.local.queryBCContractResults.Contract_Parties[i].PartyLang;
			tw.local.ContractDetails.Parties.caseInNeed.partyName = tw.local.queryBCContractResults.Contract_Parties[i].PartyName;
			tw.local.ContractDetails.Parties.caseInNeed.partyId = tw.local.queryBCContractResults.Contract_Parties[i].PartyId;
			tw.local.ContractDetails.Parties.caseInNeed.refrence = tw.local.queryBCContractResults.Contract_Parties[i].PartyRefNum;
		}
	}
}

/**-----------------------------------------------------HELPER FUNCTIONS---------------------------------------------- */
// helper function to convert string to date object
function convertToUTCDate(dateString) {
	// Split the input string by the hyphen (-) to extract year, month, and day
	var parts = dateString.split("-");
	var year = parseInt(parts[0], 10);
	var month = parseInt(parts[1], 10) - 1;
	var day = parseInt(parts[2], 10);

	// Create the Date object in UTC
	var date = new Date(Date.UTC(year, month, day));
	return date;
}

// TODO : add each split outstanding amnt  

if (tw.local.isSuccessful && tw.local.queryBCContractResults) {
	tw.local.ContractDetails.ContractCreation.amount = parseFloat(tw.local.queryBCContractResults.Amount);
	tw.local.ContractDetails.FinancialDetailsFO.collectableAmount = parseFloat(tw.local.queryBCContractResults.Amount);
	tw.local.ContractDetails.FinancialDetailsFO.outstandingAmount = parseFloat(tw.local.queryBCContractResults.OutstandingAmount);
}

